{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C01"],
      "claim": "Emtricitabine, a closely related pyrimidine NRTI, has an absolute oral bioavailability of 93% in humans, strongly supporting high oral bioavailability for the query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C45"],
      "claim": "Lamivudine, another closely related cytidine NRTI, shows absolute oral bioavailability of 87% in fasted patients, supporting high F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C33"],
      "claim": "Zalcitabine, a dideoxynucleoside NRTI with a similar sugar scaffold, has an absolute oral bioavailability of 88%, supporting high F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C51"],
      "claim": "Didanosine, a purine NRTI with less favorable absorption, still shows approximately 43% absolute oral bioavailability, above the 20% threshold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C39"],
      "claim": "Theophylline, a related xanthine, shows mean systemic availability of 91.5%, consistent with high oral bioavailability for this nucleobase-like scaffold.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "high",
  "decision_summary": "The query is stavudine, an NRTI. Highly transferable experimental evidence from closely related nucleoside reverse transcriptase inhibitors—emtricitabine, lamivudine, zalcitabine, and didanosine—consistently shows oral bioavailability values at or above the 20% threshold, with most values well above 50%. No affirmative evidence supports low bioavailability.",
  "evidence_gaps": [
    "No direct stavudine bioavailability record is present in the supplied evidence set, but the query structure is stavudine and the analogue evidence is highly transferable.",
    "Some didanosine records in children or fed conditions fall below 20%, but these are formulation- and population-specific extremes and do not outweigh the consistent high-F evidence from closer NRTI analogues."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

